import { path } from '@servicenow/sdk-build-core'
import { findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from '../test-utils'
import { gunzipSync } from 'zlib'
import { createTestContext } from '../../../test-utils'

describe('Daily Incident Processor Flow - XML to Fluent Tests', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Test 1: Trigger Validation', () => {
        test('Daily Incident Processor trigger transforms correctly', async () => {
            const project = ctx.createProject()

            // Load the XML file
            const xmlContent = loadTestFile('sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.xml', 'e2e/xml')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.xml',
                content: xmlContent,
            })

            // Verify transformation produced a file
            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts')

            const content = changedFiles[0].getContent()

            // Test 1: Verify imports
            expect(content).toContain("import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'")
            expect(content).toContain(
                "import { IntegerColumn, StringColumn, BooleanColumn } from '@servicenow/sdk/core'"
            )

            // Test 2: Verify Flow metadata
            expect(content).toContain('Flow(')
            expect(content).toContain("$id: Now.ID['687a54cb829740f6bb2a9ddb7032f419']")
            expect(content).toContain("name: 'Example_1_Daily Incident Processor'")
            expect(content).toContain('description:')

            // Test 3: Verify Daily scheduled trigger
            expect(content).toContain('trigger.scheduled.daily')
            expect(content).toContain('wfa.trigger(')

            // Test 4: Verify trigger configuration
            expect(content).toContain('run_start_time')
            expect(content).toContain('run_start_date_time')

            // Test 5: Verify trigger annotation
            expect(content).toContain("annotation: 'Run daily at 8:00 AM to process incidents'")

            // Test 6: Verify trigger time configuration with specific values
            expect(content).toContain('time: Time(')
            expect(content).toContain('hours: 2')
            expect(content).toContain('minutes: 30')
        })
    })

    describe('Test 2: Flow Variables Validation', () => {
        test('Daily Incident Processor flow variables are correctly defined', async () => {
            const project = ctx.createProject()

            // Load the XML file
            const xmlContent = loadTestFile('sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.xml', 'e2e/xml')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Test 1: Verify flowVariables object exists
            expect(content).toContain('flowVariables: {')

            // Test 2: Verify totalProcessed variable
            expect(content).toMatch(/totalProcessed:\s*IntegerColumn\({/)
            expect(content).toMatch(/label:\s*'totalProcessed'/)
            expect(content).toMatch(/mandatory:\s*true/)

            // Test 3: Verify highPriorityCount variable
            expect(content).toMatch(/highPriorityCount:\s*IntegerColumn\({/)
            expect(content).toMatch(/label:\s*'highPriorityCount'/)

            // Test 4: Verify normalPriorityCount variable
            expect(content).toMatch(/normalPriorityCount:\s*IntegerColumn\({/)
            expect(content).toMatch(/label:\s*'normalPriorityCount'/)

            // Test 5: Verify processingStatus variable
            expect(content).toMatch(/processingStatus:\s*StringColumn\({/)
            expect(content).toMatch(/label:\s*'processingStatus'/)

            // Test 6: Verify shouldContinue variable with BooleanColumn and default value
            expect(content).toMatch(/shouldContinue:\s*BooleanColumn\({/)
            expect(content).toMatch(/label:\s*'shouldContinue'/)
            expect(content).toMatch(/default:\s*true/)

            // Test 7: Verify all flow variables are mandatory
            const mandatoryMatches = content.match(/mandatory:\s*true/g)
            expect(mandatoryMatches).toBeTruthy()
            expect(mandatoryMatches!.length).toBeGreaterThanOrEqual(5) // All 5 flow variables should be mandatory

            // Test 8: Verify flow variables are initialized in first setFlowVariables
            expect(content).toContain('wfa.flowLogic.setFlowVariables(')
            expect(content).toContain("annotation: 'Initialize processing counters and status'")
            expect(content).toContain('totalProcessed: 0')
            expect(content).toContain('highPriorityCount: 0')
            expect(content).toContain('normalPriorityCount: 0')
            expect(content).toContain("processingStatus: 'STARTED'")
            expect(content).toContain('shouldContinue: true')

            // Test 9: Verify flow variables are accessed via _params.flowVariables
            expect(content).toContain('_params.flowVariables')
            expect(content).toContain('wfa.dataPill(_params.flowVariables')

            // Test 10: Verify flow variables are updated in second setFlowVariables
            expect(content).toContain("annotation: 'Set processing complete status'")
            expect(content).toContain("processingStatus: 'COMPLETED'")
            expect(content).toContain('shouldContinue: false')

            // Test 11: Verify flow variables used in final summary log
            expect(content).toContain('=== DAILY INCIDENT PROCESSOR SUMMARY ===')
            expect(content).toMatch(/_params\.flowVariables\.processingStatus/)
            expect(content).toMatch(/_params\.flowVariables\.totalProcessed/)
            expect(content).toMatch(/_params\.flowVariables\.highPriorityCount/)
            expect(content).toMatch(/_params\.flowVariables\.normalPriorityCount/)
            expect(content).toMatch(/_params\.flowVariables\.shouldContinue/)
        })
    })

    describe('Test 3: Flow Logic Constructs', () => {
        test('Daily Incident Processor contains all required flow logic constructs', async () => {
            const project = ctx.createProject()

            // Load the XML file
            const xmlContent = loadTestFile('sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.xml', 'e2e/xml')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Test 1: Verify initial log action
            expect(content).toContain('action.core.log')
            expect(content).toContain("annotation: 'Log flow execution start'")
            expect(content).toContain('Daily Incident Processor started')

            // Test 2: Verify SET FLOW VARIABLES (first call)
            expect(content).toContain('wfa.flowLogic.setFlowVariables(')
            expect(content).toContain("annotation: 'Initialize processing counters and status'")

            // Test 3: Verify lookUpRecords action with full configuration
            expect(content).toContain('action.core.lookUpRecords')
            expect(content).toContain("annotation: 'Query all unassigned incidents'")
            expect(content).toContain("table: 'incident'")
            expect(content).toContain("conditions: 'assignment_groupISEMPTY^active=true^ORDERBYpriority'")
            expect(content).toContain('max_results: 1000')
            expect(content).toContain("sort_type: 'sort_asc'")

            // Test 4: Verify IF condition (check if incidents found)
            expect(content).toContain('wfa.flowLogic.if(')
            expect(content).toMatch(/actionInstance_3\.Count.*=0/)
            expect(content).toContain("annotation: 'Check if there are incidents to process'")

            // Test 5: Verify END FLOW
            expect(content).toContain('wfa.flowLogic.endFlow(')
            expect(content).toContain("annotation: 'End flow early - no incidents to process'")

            // Test 6: Verify log after IF (incidents found)
            expect(content).toContain('Found ${wfa.dataPill(actionInstance_3.Count')
            expect(content).toContain('unassigned incidents. Beginning processing')

            // Test 7: Verify FOR EACH loop
            expect(content).toContain('wfa.flowLogic.forEach(')
            expect(content).toContain('wfa.dataPill(actionInstance_3.Records')
            expect(content).toContain("annotation: 'Process each unassigned incident'")

            // Test 8: Verify nested IF statements inside forEach (Priority 1)
            expect(content).toContain("annotation: 'Handle Priority 1 - Critical incidents'")
            expect(content).toContain("log_level: 'error'")
            expect(content).toContain('CRITICAL: Incident')

            // Test 9: Verify ELSE IF for Priority 2
            expect(content).toContain('wfa.flowLogic.elseIf(')
            expect(content).toContain("annotation: 'Handle Priority 2 - High priority incidents'")
            expect(content).toContain("log_level: 'warn'")
            expect(content).toContain('HIGH PRIORITY: Incident')

            // Test 10: Verify ELSE IF for Priority 3
            expect(content).toContain("annotation: 'Handle Priority 3 - Moderate priority'")
            expect(content).toContain('Moderate priority incident')

            // Test 11: Verify ELSE IF for Priority 4 and 5 (compound condition)
            expect(content).toMatch(/priority.*=4\^NQ.*priority.*=5/)
            // Test 12: Verify ELSE statement with EXIT LOOP
            expect(content).toContain('wfa.flowLogic.else(')
            expect(content).toContain('Exiting loop if priority is not set')
            expect(content).toContain('wfa.flowLogic.exitLoop(')

            // Test 13: Note - forEach template syntax removed in new implementation
            // New: Uses item_8 parameter directly

            // Test 14: Note - UUID-based template syntax removed in new implementation
            // Old: {{46d167c6-cead-4a7d-acc5-54b3eed6368e.item.priority}}
            // New: Uses wfa.dataPill(item_8.priority, 'choice') directly

            // Test 15: Verify priority conditions (1, 2, 3) using new syntax
            expect(content).toContain("wfa.dataPill(item_8.priority, 'choice')")
            expect(content).toMatch(/priority.*'choice'\)\}=1/)
            expect(content).toMatch(/priority.*'choice'\)\}=2/)
            expect(content).toMatch(/priority.*'choice'\)\}=3/)

            // Test 16: Verify second SET FLOW VARIABLES call
            expect(content).toContain("annotation: 'Set processing complete status'")

            // Test 17: Verify final summary log
            expect(content).toContain("annotation: 'Log comprehensive execution summary'")
            expect(content).toContain('=== DAILY INCIDENT PROCESSOR SUMMARY ===')
        })
    })

    describe('Test 4: Fluent to XML Bidirectional Transformation', () => {
        test('Flow metadata transforms correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts',
                'e2e/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            expect(merged['sys_hub_flow'].length).toBe(1)

            const flow = merged['sys_hub_flow'][0]
            expect(flow.name).toBe('Example_1_Daily Incident Processor')
            expect(flow.description).toContain('Triggers - Daily')
            expect(flow.description).toContain('Flow Variables')
            expect(flow.description).toContain('For Each')
            expect(flow.type).toBe('flow')
            expect(flow.generation_source).toBe('fluent')
        })

        test('Flow variables transform correctly with proper types and defaults', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts',
                'e2e/fluent'
            )

            // Verify flow variables
            expect(merged['sys_hub_flow_variable']).toBeDefined()
            expect(merged['sys_hub_flow_variable'].length).toBe(5)

            const variables = merged['sys_hub_flow_variable']
            const variablesByElement = Object.fromEntries(variables.map((v: any) => [v.element, v]))

            // Test totalProcessed
            expect(variablesByElement['totalProcessed']).toBeDefined()
            expect(variablesByElement['totalProcessed'].label).toBe('totalProcessed')
            expect(variablesByElement['totalProcessed'].internal_type).toBe('integer')
            expect(variablesByElement['totalProcessed'].mandatory).toBe(true)

            // Test highPriorityCount
            expect(variablesByElement['highPriorityCount']).toBeDefined()
            expect(variablesByElement['highPriorityCount'].label).toBe('highPriorityCount')
            expect(variablesByElement['highPriorityCount'].internal_type).toBe('integer')

            // Test normalPriorityCount
            expect(variablesByElement['normalPriorityCount']).toBeDefined()
            expect(variablesByElement['normalPriorityCount'].label).toBe('normalPriorityCount')
            expect(variablesByElement['normalPriorityCount'].internal_type).toBe('integer')

            // Test processingStatus
            expect(variablesByElement['processingStatus']).toBeDefined()
            expect(variablesByElement['processingStatus'].label).toBe('processingStatus')
            expect(variablesByElement['processingStatus'].internal_type).toBe('string')

            // Test shouldContinue with default value
            expect(variablesByElement['shouldContinue']).toBeDefined()
            expect(variablesByElement['shouldContinue'].label).toBe('shouldContinue')
            expect(variablesByElement['shouldContinue'].internal_type).toBe('boolean')
            expect(variablesByElement['shouldContinue'].default_value).toBe(true)
        })

        test('Trigger transforms correctly with time configuration', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts',
                'e2e/fluent'
            )

            // Verify trigger instance
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            expect(merged['sys_hub_trigger_instance_v2'].length).toBe(1)

            const trigger = merged['sys_hub_trigger_instance_v2'][0]
            expect(trigger.sys_id).toBe('96bd6a7ad88542fea2eb94623c4eedba')
            expect(trigger.comment).toBe('Run daily at 8:00 AM to process incidents')

            // Verify trigger inputs contain time configuration
            if (trigger.trigger_inputs) {
                const triggerInputs = unzipInputArray(trigger.trigger_inputs)
                const timeInput = findInput(triggerInputs, 'time')
                expect(timeInput).toBeDefined()
                expect(timeInput.value).toContain('02:30:00')
            }
        })

        test('Action instances transform correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts',
                'e2e/fluent'
            )

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actions = merged['sys_hub_action_instance_v2']

            // Should have: 1 lookUpRecords + 7 log actions = 8 total
            expect(actions.length).toBeGreaterThanOrEqual(8)

            // Find lookUpRecords action
            const lookUpAction = actions.find((a: any) => a.sys_id === 'f311817831d2456d8dc87a00ae5ec749')
            expect(lookUpAction).toBeDefined()
            expect(lookUpAction.comment).toBe('Query all unassigned incidents')

            const lookUpInputs = unzipInputArray(lookUpAction.values)
            const tableInput = findInput(lookUpInputs, 'table')
            expect(tableInput.value).toBe('incident')

            const conditionsInput = findInput(lookUpInputs, 'conditions')
            expect(conditionsInput.value).toBe('assignment_groupISEMPTY^active=true^ORDERBYpriority')

            // Find first log action
            const firstLogAction = actions.find((a: any) => a.sys_id === '1edb09e184564a89ad77168b13fcbe6d')
            expect(firstLogAction).toBeDefined()
            expect(firstLogAction.comment).toBe('Log flow execution start')
        })

        test('Flow logic instances transform correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts',
                'e2e/fluent'
            )

            // Verify flow logic instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogics = merged['sys_hub_flow_logic_instance_v2']

            // Should have: 2 setFlowVariables, 1 if, 1 forEach, 4 elseIf, 1 else, 1 endFlow, 1 exitLoop = 11 total
            expect(flowLogics.length).toBeGreaterThanOrEqual(11)

            // Verify setFlowVariables instances by finding them by sys_id
            const firstSetFlowVars = flowLogics.find((fl: any) => fl.sys_id === '983e1ade48044cbb8659696d072d0439')
            const secondSetFlowVars = flowLogics.find((fl: any) => fl.sys_id === '5a60803f42b647c3bcb8366c91cbc3fa')
            expect(firstSetFlowVars).toBeDefined()
            expect(secondSetFlowVars).toBeDefined()

            // Verify setFlowVariables comments
            expect(firstSetFlowVars.comment).toBe('Initialize processing counters and status')
            expect(secondSetFlowVars.comment).toBe('Set processing complete status')

            // Verify IF statement
            const ifStatement = flowLogics.find((fl: any) => fl.sys_id === '0c627e4456294872beae75744c2b5694')
            expect(ifStatement).toBeDefined()
            expect(ifStatement.comment).toBe('Check if there are incidents to process')

            // Verify endFlow
            const endFlow = flowLogics.find((fl: any) => fl.sys_id === 'e8d8da55cc30424d9eef50462919b8cd')
            expect(endFlow).toBeDefined()
            expect(endFlow.comment).toBe('End flow early - no incidents to process')

            // Verify exitLoop
            const exitLoop = flowLogics.find((fl: any) => fl.sys_id === 'dee56367b15af6d0f8774074995d9952')
            expect(exitLoop).toBeDefined()
            expect(exitLoop.comment).toBe('exit loop')
        })

        test('forEach loop transforms correctly with proper structure', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts',
                'e2e/fluent'
            )

            const flowLogics = merged['sys_hub_flow_logic_instance_v2']

            // Find the forEach loop
            const forEachLoop = flowLogics.find((fl: any) => fl.sys_id === '46d167c6cead4a7dacc554b3eed6368e')
            expect(forEachLoop).toBeDefined()
            expect(forEachLoop.comment).toBe('Process each unassigned incident')
            expect(forEachLoop.logic_definition).toBe('098e1dc5c3e232002841b63b12d3ae33') // forEach logic_definition

            // Verify forEach values contain items reference
            const forEachValues = JSON.parse(gunzipSync(Buffer.from(forEachLoop.values, 'base64')).toString('utf8'))
            expect(forEachValues.inputs).toBeDefined()

            const itemsInput = forEachValues.inputs.find((input: any) => input.name === 'items')
            expect(itemsInput).toBeDefined()
            expect(itemsInput.value).toContain('f3118178-31d2-456d-8dc8-7a00ae5ec749.Records')
        })

        test('forEach child flow logic (if/elseIf/else) transforms correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts',
                'e2e/fluent'
            )

            const flowLogics = merged['sys_hub_flow_logic_instance_v2']

            // Find forEach to get its ui_id
            const forEachLoop = flowLogics.find((fl: any) => fl.sys_id === '46d167c6cead4a7dacc554b3eed6368e')
            expect(forEachLoop).toBeDefined()

            // Find child flow logic instances (should have parent_ui_id = forEach ui_id)
            const forEachChildren = flowLogics.filter((fl: any) => fl.parent_ui_id === forEachLoop.ui_id)
            expect(forEachChildren.length).toBeGreaterThan(0)

            // Verify Priority 1 IF statement
            const priority1If = flowLogics.find((fl: any) => fl.sys_id === '00097b978c2644278eb80a4321cc2f51')
            expect(priority1If).toBeDefined()
            expect(priority1If.comment).toBe('Handle Priority 1 - Critical incidents')
            expect(priority1If.parent_ui_id).toBe(forEachLoop.ui_id)

            // Verify Priority 2 ELSE IF statement
            const priority2ElseIf = flowLogics.find((fl: any) => fl.sys_id === 'd6245c6b9c9442f5a336410138f3ea44')
            expect(priority2ElseIf).toBeDefined()
            expect(priority2ElseIf.comment).toBe('Handle Priority 2 - High priority incidents')

            // Verify Priority 3 ELSE IF statement
            const priority3ElseIf = flowLogics.find((fl: any) => fl.sys_id === '031692437d94496e8ed7e77809138edc')
            expect(priority3ElseIf).toBeDefined()
            expect(priority3ElseIf.comment).toBe('Handle Priority 3 - Moderate priority')

            // Verify Priority 4/5 ELSE IF statement (if it exists in new implementation)
            const priority45ElseIf = flowLogics.find((fl: any) => fl.sys_id === 'b565efe3b15af6d0f8774074995d998e')
            if (priority45ElseIf) {
                expect(priority45ElseIf.comment).toBe('Else if the Priority is Low or Planning')
            }

            // Verify ELSE statement (if it exists in new implementation)
            const elseStatement = flowLogics.find((fl: any) => fl.sys_id === '79c56f27b15af6d0f8774074995d9973')
            if (elseStatement) {
                expect(elseStatement.comment).toBe('else')
            }
        })

        test('DataPills in log messages use wfa.dataPill format', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts',
                'e2e/fluent'
            )

            const actions = merged['sys_hub_action_instance_v2']

            // Find log action inside forEach (Priority 1 critical log)
            const criticalLog = actions.find((a: any) => a.sys_id === 'd2829217fc644abdbfc4482656ea18a1')
            expect(criticalLog).toBeDefined()

            const criticalLogInputs = unzipInputArray(criticalLog.values)
            const logMessageInput = findInput(criticalLogInputs, 'log_message')
            expect(logMessageInput).toBeDefined()

            // Log message should contain datapill reference to forEach item
            expect(logMessageInput.value).toContain('CRITICAL: Incident')
            // Note: New implementation uses different datapill references (assignment_group, rfc.category instead of number)
            expect(logMessageInput.value).toContain('46d167c6-cead-4a7d-acc5-54b3eed6368e.item')

            // Find final summary log action
            const summaryLog = actions.find((a: any) => a.sys_id === '77ddc9bbeb8c4cceb3d228c9428b115b')
            expect(summaryLog).toBeDefined()
            expect(summaryLog.comment).toBe('Log comprehensive execution summary')

            const summaryLogInputs = unzipInputArray(summaryLog.values)
            const summaryMessageInput = findInput(summaryLogInputs, 'log_message')
            expect(summaryMessageInput.value).toContain('=== DAILY INCIDENT PROCESSOR SUMMARY ===')
            expect(summaryMessageInput.value).toContain('flow_variable.processingStatus')
            expect(summaryMessageInput.value).toContain('flow_variable.totalProcessed')
        })

        test('All annotations are preserved as comments in XML', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'sys_hub_flow_687a54cb829740f6bb2a9ddb7032f419.now.ts',
                'e2e/fluent'
            )

            // Check trigger annotation
            const trigger = merged['sys_hub_trigger_instance_v2'][0]
            expect(trigger.comment).toBe('Run daily at 8:00 AM to process incidents')

            // Check action annotations
            const actions = merged['sys_hub_action_instance_v2']
            const firstLog = actions.find((a: any) => a.sys_id === '1edb09e184564a89ad77168b13fcbe6d')
            expect(firstLog.comment).toBe('Log flow execution start')

            const lookUpAction = actions.find((a: any) => a.sys_id === 'f311817831d2456d8dc87a00ae5ec749')
            expect(lookUpAction.comment).toBe('Query all unassigned incidents')

            // Check flow logic annotations
            const flowLogics = merged['sys_hub_flow_logic_instance_v2']
            const forEach = flowLogics.find((fl: any) => fl.sys_id === '46d167c6cead4a7dacc554b3eed6368e')
            expect(forEach.comment).toBe('Process each unassigned incident')

            const exitLoop = flowLogics.find((fl: any) => fl.sys_id === 'dee56367b15af6d0f8774074995d9952')
            expect(exitLoop.comment).toBe('exit loop')
        })
    })
})
